package com.coloroverlay;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("coloroverlay")
public interface ColorOverlayConfig extends Config
{
    @ConfigItem(keyName = "color", name = "Tint color", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default Color color() { return new Color(160, 65, 255); }

    @ConfigItem(keyName = "strength", name = "Tint strength (%)", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default int strength() { return 25; }

    @ConfigItem(keyName = "trippyMode", name = "Trippy Mode", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default boolean trippyMode() { return false; }

    @ConfigItem(keyName = "trippyStyle", name = "Trippy style", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default TrippyStyle trippyStyle() { return TrippyStyle.RAINBOW_CYCLE; }

    @ConfigItem(keyName = "cycleSeconds", name = "Effect cycle (seconds)", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default int cycleSeconds() { return 15; }

    @ConfigItem(keyName = "palette", name = "Color palette", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default PalettePreset palette() { return PalettePreset.ORIGINAL; }

    @ConfigItem(keyName = "colorCount", name = "Number of colors", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default int colorCount() { return 6; }

    @ConfigItem(keyName = "customColors", name = "Custom colors", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default String customColors() { return "#002244,#0088AA,#88FFDD"; }

    @ConfigItem(keyName = "points", name = "Kaleidoscope points", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default int points() { return 6; }

    @ConfigItem(keyName = "layers", name = "Kaleidoscope layers", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default int layers() { return 3; }

    @ConfigItem(keyName = "enabled", name = "Enable overlay", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default boolean enabled() { return true; }

    @ConfigItem(keyName = "savedPalettes", name = "Saved palettes", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default String savedPalettes() { return "[]"; }

    @ConfigItem(keyName = "savedPaletteName", name = "Selected saved palette", description = "Managed in the rainbow Trippy Mode sidebar.", hidden = true)
    default String savedPaletteName() { return ""; }

}

package com.coloroverlay;

import com.google.inject.Provides;
import com.google.gson.Gson;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "Trippy Mode", description = "A world tint with optional Trippy styles", tags = {"color", "tint", "trippy", "rainbow"})
public class ColorOverlayPlugin extends Plugin
{
    @Inject private OverlayManager overlayManager;
    @Inject private WorldTintOverlay overlay;
    @Inject private ConfigManager manager;
    @Inject private ColorOverlayConfig config;
    @Inject private Gson gson;
    @Inject private Client client;
    @Inject private ClientToolbar toolbar;
    @Inject private ColorPickerManager picker;
    private OverlayPanel panel;
    private NavigationButton navigation;
    private volatile boolean running;

    @Provides ColorOverlayConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ColorOverlayConfig.class);
    }

    @Override protected void startUp()
    {
        running = true;
        overlay.resetAnimation(); overlayManager.add(overlay);
        SwingUtilities.invokeLater(() -> {
            if (!running) { return; }
            panel = new OverlayPanel(client, picker, config, new OverlayControls(manager, config, gson));
            BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
            Graphics2D graphics = icon.createGraphics();
            try {
                for (int i = 0; i < 6; i++) {
                    graphics.setColor(Color.getHSBColor(i / 6f, .9f, 1f));
                    graphics.fillArc(i, i + 2, 16 - i * 2, 24 - i * 2, 0, 180);
                }
                graphics.setComposite(java.awt.AlphaComposite.Clear);
                graphics.fillOval(6, 8, 4, 12);
            } finally { graphics.dispose(); }
            navigation = NavigationButton.builder().tooltip("Trippy Mode").icon(icon).priority(6).panel(panel).build();
            toolbar.addNavigation(navigation);
        });
    }

    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if ("coloroverlay".equals(event.getGroup())) {
            SwingUtilities.invokeLater(() -> { if (running && panel != null) { panel.refresh(); } });
        }
    }

    @Override protected void shutDown()
    {
        running = false;
        overlayManager.remove(overlay);
        SwingUtilities.invokeLater(() -> {
            if (navigation != null) { toolbar.removeNavigation(navigation); navigation = null; }
            if (panel != null) { panel.disposePanel(); panel = null; }
        });
    }
}

package com.coloroverlay;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

final class EffectPalette
{
    private final Color[] colors;
    private EffectPalette(Color[] colors) { this.colors = colors; }

    static EffectPalette create(PalettePreset preset, String custom, int count)
    {
        if (preset == PalettePreset.ORIGINAL) { return new EffectPalette(null); }
        List<Color> parsed = new ArrayList<>();
        String source = preset == PalettePreset.CUSTOM ? custom : preset.colors;
        if (source != null)
        {
            for (String token : source.split("[,;\\s]+"))
            {
                String hex = token.startsWith("#") ? token.substring(1) : token;
                if (hex.matches("[0-9a-fA-F]{6}")) { parsed.add(new Color(Integer.parseInt(hex, 16))); }
                if (parsed.size() == 16) { break; }
            }
        }
        // Empty or malformed custom lists fall back to a known palette, without interrupting rendering.
        if (parsed.isEmpty()) { return create(PalettePreset.RAINBOW, "", count); }
        Color[] anchors = parsed.toArray(new Color[0]);
        int size = Math.max(1, Math.min(16, count));
        Color[] selected = new Color[size];
        for (int i = 0; i < size; i++)
        {
            // Preserve the first/last anchors when changing the requested palette size.
            selected[i] = preset == PalettePreset.CUSTOM ? anchors[Math.min(i, anchors.length - 1)]
                : sampleLine(anchors, size == 1 ? 0 : i * (anchors.length - 1.0) / (size - 1));
        }
        return new EffectPalette(selected);
    }

    Color sample(double position)
    {
        double fraction = position - Math.floor(position);
        if (colors == null) { return Color.getHSBColor((float) fraction, 1f, 1f); }
        double index = fraction * colors.length;
        int start = (int) index;
        return mix(colors[start], colors[(start + 1) % colors.length], index - start);
    }

    private static Color sampleLine(Color[] colors, double index)
    {
        int start = (int) index;
        return mix(colors[start], colors[Math.min(start + 1, colors.length - 1)], index - start);
    }

    private static Color mix(Color a, Color b, double amount)
    {
        return new Color((int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * amount),
            (int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * amount),
            (int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * amount));
    }
}

package com.coloroverlay;

import com.google.gson.Gson;

import java.awt.Color;
import java.util.List;
import net.runelite.client.config.ConfigManager;

final class OverlayControls
{
    private final ConfigManager manager;
    private final ColorOverlayConfig config;
    private final Gson gson;
    OverlayControls(ConfigManager manager, ColorOverlayConfig config, Gson gson) {
        this.manager = manager; this.config = config; this.gson = gson;
    }
    List<PaletteLibrary.Entry> saved() { return PaletteLibrary.read(config.savedPalettes(), gson); }
    void set(String key, Object value) { manager.setConfiguration("coloroverlay", key, value); }

    Color[] colors()
    {
        int count = Math.max(1, Math.min(16, config.colorCount()));
        EffectPalette palette = EffectPalette.create(config.palette(), config.customColors(), count);
        Color[] colors = new Color[count];
        for (int i = 0; i < count; i++) { colors[i] = palette.sample(i / (double) count); }
        return colors;
    }

    void selectPreset(PalettePreset preset)
    {
        set("savedPaletteName", ""); set("palette", preset);
    }

    void selectSaved(PaletteLibrary.Entry entry)
    {
        set("customColors", entry.colors); set("colorCount", entry.count);
        set("palette", PalettePreset.CUSTOM); set("savedPaletteName", entry.name);
    }

    void editColor(int index, Color color)
    {
        Color[] visible = colors();
        if (index < 0 || index >= visible.length) { return; }
        EffectPalette hidden = EffectPalette.create(PalettePreset.CUSTOM, config.customColors(), 16);
        Color[] all = new Color[16];
        for (int i = 0; i < 16; i++) {
            all[i] = i < visible.length ? visible[i] : hidden.sample(i / 16.0);
        }
        all[index] = color;
        set("customColors", encode(all)); set("savedPaletteName", ""); set("palette", PalettePreset.CUSTOM);
    }

    void count(int count)
    {
        set("savedPaletteName", ""); set("colorCount", Math.max(1, Math.min(16, count)));
    }

    void save(String name)
    {
        name = name.trim();
        if (name.isEmpty() || name.length() > 40) { throw new IllegalArgumentException("Use a palette name with 1–40 characters."); }
        final String selectedName = name;
        List<PaletteLibrary.Entry> entries = saved();
        entries.removeIf(entry -> entry.name.equalsIgnoreCase(selectedName));
        Color[] colors = colors();
        PaletteLibrary.Entry entry = new PaletteLibrary.Entry(name, encode(colors), colors.length);
        entries.add(entry); set("savedPalettes", PaletteLibrary.write(entries, gson)); selectSaved(entry);
    }

    void delete(String name)
    {
        List<PaletteLibrary.Entry> entries = saved();
        entries.removeIf(entry -> entry.name.equals(name));
        set("savedPalettes", PaletteLibrary.write(entries, gson)); set("savedPaletteName", "");
    }

    private static String encode(Color[] colors)
    {
        StringBuilder result = new StringBuilder();
        for (Color color : colors) {
            if (result.length() > 0) { result.append(','); }
            result.append(String.format("#%06X", color.getRGB() & 0xffffff));
        }
        return result.toString();
    }
}

package com.coloroverlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.List;
import java.util.Objects;
import javax.swing.*;
import net.runelite.api.Client;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

final class OverlayPanel extends PluginPanel
{
    private final Client client;
    private final ColorPickerManager picker;
    private final ColorOverlayConfig config;
    private final OverlayControls controls;
    private boolean refreshing;
    private boolean active = true;
    private final JCheckBox enabled = new JCheckBox("Enable overlay");
    private final JCheckBox trippy = new JCheckBox("Trippy Mode");
    private final JButton tint = new JButton();
    private final JSpinner strength = spinner(25, 0, 100);
    private final JComboBox<TrippyStyle> styles = new JComboBox<>(TrippyStyle.values());
    private final JSpinner cycle = spinner(15, 2, 120);
    private final JComboBox<Object> palettes = new JComboBox<>();
    private final JSpinner count = spinner(6, 1, 16);
    private final JPanel swatches = new JPanel(new GridLayout(0, 2, 6, 6));
    private final JTextField name = new JTextField();
    private final JButton save = new JButton("Save / update palette");
    private final JButton delete = new JButton("Delete saved palette");
    private final JLabel status = new JLabel(" ");
    private final JSpinner points = spinner(6, 3, 24);
    private final JSpinner layers = spinner(3, 1, 12);

    OverlayPanel(Client client, ColorPickerManager picker, ColorOverlayConfig config, OverlayControls controls)
    {
        this.client = client; this.picker = picker; this.config = config; this.controls = controls;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        add(new JLabel("Trippy Mode")); add(Box.createVerticalStrut(10));
        add(enabled); row("Tint color", tint); row("Tint strength (%)", strength);
        add(trippy); row("Trippy style", styles); row("Effect cycle (seconds)", cycle);
        row("Color palette", palettes); row("Number of colors", count);
        add(Box.createVerticalStrut(8)); add(swatches);
        row("Palette name", name); add(save); add(delete); add(status);
        row("Kaleidoscope points", points); row("Kaleidoscope layers", layers);
        add(new JLabel("<html>Click a color to edit it.<br>Editing a preset creates a custom copy.<br>Save uses the currently visible colors.<br>Same name updates an existing palette.</html>"));
        palettes.setRenderer(new DefaultListCellRenderer() {
            @Override public java.awt.Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected, boolean focus) {
                Object label = value instanceof PaletteLibrary.Entry ? "Saved: " + ((PaletteLibrary.Entry) value).name : value;
                return super.getListCellRendererComponent(list, label, index, selected, focus);
            }
        });
        enabled.addActionListener(e -> { if (!refreshing) { controls.set("enabled", enabled.isSelected()); } });
        trippy.addActionListener(e -> { if (!refreshing) { controls.set("trippyMode", trippy.isSelected()); } });
        strength.addChangeListener(e -> change("strength", strength));
        cycle.addChangeListener(e -> change("cycleSeconds", cycle));
        points.addChangeListener(e -> change("points", points));
        layers.addChangeListener(e -> change("layers", layers));
        styles.addActionListener(e -> { if (!refreshing) { controls.set("trippyStyle", styles.getSelectedItem()); refresh(); } });
        palettes.addActionListener(e -> {
            if (refreshing) { return; }
            Object selected = palettes.getSelectedItem();
            if (selected instanceof PaletteLibrary.Entry) { controls.selectSaved((PaletteLibrary.Entry) selected); }
            else if (selected instanceof PalettePreset) { controls.selectPreset((PalettePreset) selected); }
            refresh();
        });
        count.addChangeListener(e -> { if (!refreshing) { controls.count((int) count.getValue()); refresh(); } });
        tint.addActionListener(e -> {
            RuneliteColorPicker dialog = picker.create(client, config.color(), "Tint color", false);
            dialog.setOnClose(color -> { if (active) { controls.set("color", color); refresh(); } });
            dialog.setVisible(true);
        });
        save.addActionListener(e -> {
            try { controls.save(name.getText()); refresh(); status.setText("Palette saved."); }
            catch (IllegalArgumentException exception) { status.setText("Use a name with 1-40 characters."); }
        });
        delete.addActionListener(e -> {
            if (!config.savedPaletteName().isEmpty()) {
                controls.delete(config.savedPaletteName()); name.setText(""); refresh(); status.setText("Saved palette deleted.");
            }
        });
        refresh();
    }

    private static JSpinner spinner(int value, int min, int max) { return new JSpinner(new SpinnerNumberModel(value, min, max, 1)); }
    private void change(String key, JSpinner spinner) { if (!refreshing) { controls.set(key, spinner.getValue()); } }
    private void row(String label, JComponent component)
    {
        add(Box.createVerticalStrut(8)); add(new JLabel(label));
        component.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30)); add(component);
    }
    void disposePanel() { active = false; }

    void refresh()
    {
        if (!active) { return; }
        refreshing = true;
        try
        {
            enabled.setSelected(config.enabled()); trippy.setSelected(config.trippyMode());
            strength.setValue(Math.max(0, Math.min(100, config.strength())));
            cycle.setValue(Math.max(2, Math.min(120, config.cycleSeconds())));
            points.setValue(Math.max(3, Math.min(24, config.points())));
            layers.setValue(Math.max(1, Math.min(12, config.layers())));
            count.setValue(Math.max(1, Math.min(16, config.colorCount())));
            styles.setSelectedItem(config.trippyStyle());
            boolean kaleido = config.trippyStyle().name().startsWith("KALEIDOSCOPE");
            points.setEnabled(kaleido); layers.setEnabled(kaleido);
            updateColor(tint, config.color());
            palettes.removeAllItems();
            for (PalettePreset preset : PalettePreset.values()) { palettes.addItem(preset); }
            List<PaletteLibrary.Entry> saved = controls.saved();
            Object selected = config.palette();
            for (PaletteLibrary.Entry entry : saved) {
                palettes.addItem(entry);
                if (entry.name.equals(config.savedPaletteName())) { selected = entry; }
            }
            palettes.setSelectedItem(selected);
            delete.setEnabled(selected instanceof PaletteLibrary.Entry);
            if (selected instanceof PaletteLibrary.Entry) { name.setText(((PaletteLibrary.Entry) selected).name); }
            swatches.removeAll();
            Color[] colors = controls.colors();
            for (int i = 0; i < colors.length; i++)
            {
                final int index = i;
                JButton button = new JButton("Color " + (i + 1));
                updateColor(button, colors[i]);
                button.addActionListener(e -> {
                    String original = config.customColors();
                    PalettePreset preset = config.palette();
                    int size = config.colorCount();
                    RuneliteColorPicker dialog = picker.create(client, colors[index], "Palette color " + (index + 1), false);
                    dialog.setOnClose(color -> {
                        // A picker opened for an old palette should not modify a newly selected palette.
                        if (active && preset == config.palette() && size == config.colorCount()
                            && Objects.equals(original, config.customColors())) {
                            controls.editColor(index, color); refresh();
                        }
                    });
                    dialog.setVisible(true);
                });
                swatches.add(button);
            }
            revalidate(); repaint();
        }
        finally { refreshing = false; }
    }

    private static void updateColor(JButton button, Color color)
    {
        button.setBackground(color); button.setOpaque(true); button.setBorderPainted(false);
        button.setForeground(color.getRed() * .299 + color.getGreen() * .587 + color.getBlue() * .114 > 140 ? Color.BLACK : Color.WHITE);
        button.setToolTipText(String.format("#%06X - click to choose", color.getRGB() & 0xffffff));
        if (!button.getText().startsWith("Color ")) { button.setText(String.format("#%06X", color.getRGB() & 0xffffff)); }
    }
}

package com.coloroverlay;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;

final class PaletteLibrary
{
    static final class Entry
    {
        String name;
        String colors;
        int count;
        Entry(String name, String colors, int count) { this.name = name; this.colors = colors; this.count = count; }
        @Override public String toString() { return name; }
    }

    static List<Entry> read(String json, Gson gson)
    {
        List<Entry> entries = new ArrayList<>();
        try
        {
            Entry[] parsed = gson.fromJson(json, Entry[].class);
            if (parsed != null) {
                for (Entry entry : parsed) {
                    if (entry != null && entry.name != null && !entry.name.trim().isEmpty()
                        && entry.colors != null && entry.count >= 1 && entry.count <= 16) {
                        entries.removeIf(old -> old.name.equalsIgnoreCase(entry.name));
                        entries.add(entry);
                    }
                }
            }
        }
        catch (RuntimeException ignored) { /* Keep malformed storage from breaking the plugin. */ }
        return entries;
    }

    static String write(List<Entry> entries, Gson gson) { return gson.toJson(entries); }
}

package com.coloroverlay;

public enum PalettePreset
{
    ORIGINAL("Original colors", ""),
    RAINBOW("Rainbow", "#FF0000,#FFFF00,#00FF00,#00FFFF,#0000FF,#FF00FF"),
    OCEAN("Ocean", "#062A78,#0077B6,#00B4D8,#90E0EF"),
    PASTEL("Pastel", "#FFADAD,#FFD6A5,#FDFFB6,#CAFFBF,#BDB2FF,#FFC6FF"),
    SUNSET("Sunset", "#FFB347,#FF7043,#E94057,#8A2387,#38205C"),
    FOREST("Forest", "#153B24,#2D6A4F,#74C69D,#D8F3DC"),
    NEON("Neon", "#FF00C8,#7400FF,#00E5FF,#A8FF00"),
    CUSTOM("Custom colors", "");

    final String colors;
    private final String label;
    PalettePreset(String label, String colors) { this.label = label; this.colors = colors; }
    @Override public String toString() { return label; }
}

package com.coloroverlay;

import java.awt.Color;

final class TintColor
{
    private TintColor() {}

    static Color at(Color base, int strength, boolean trippy, int cycleSeconds, double elapsedSeconds)
    {
        return at(base, strength, trippy, TrippyStyle.RAINBOW_CYCLE, cycleSeconds, elapsedSeconds, 0, 0);
    }

    static Color at(Color base, int strength, boolean trippy, TrippyStyle style,
        int cycleSeconds, double elapsedSeconds, double x, double y)
    {
        return at(base, strength, trippy, style, cycleSeconds, elapsedSeconds, x, y,
            EffectPalette.create(PalettePreset.ORIGINAL, "", 6), 6, 3);
    }

    static Color at(Color base, int strength, boolean trippy, TrippyStyle style,
        int cycleSeconds, double elapsedSeconds, double x, double y, EffectPalette palette, int points, int layers)
    {
        double opacity = clamp(strength) / 100.0;
        Color rgb = base;
        if (trippy)
        {
            double phase = elapsedSeconds / Math.max(2, Math.min(120, cycleSeconds));
            double hue = phase;
            int sectors = Math.max(3, Math.min(24, points));
            double repetitions = Math.max(1, Math.min(12, layers));
            switch (style)
            {
                case RAINBOW_WAVE:
                    hue += x + 0.18 * Math.sin(2 * Math.PI * (y + phase));
                    break;
                case COLOR_SWIRL:
                    double radius = Math.hypot(x, y);
                    // Fade the angular term at the center to avoid a sharp seam or singularity.
                    hue += radius * 1.5 + 0.35 * Math.min(1, radius * 3)
                        * Math.sin(3 * Math.atan2(y, x) + radius * 8 - phase * Math.PI * 2);
                    break;
                case KALEIDOSCOPE:
                    double kaleidoRadius = Math.hypot(x, y);
                    double petals = Math.cos(sectors * Math.atan2(y, x));
                    hue += kaleidoRadius * repetitions * 2 / 3 + 0.3 * Math.min(1, kaleidoRadius * 4)
                        * petals * Math.sin(kaleidoRadius * repetitions * 10 / 3 - phase * Math.PI * 2);
                    break;
                case KALEIDOSCOPE_STARS:
                    double starRadius = Math.hypot(x, y);
                    double star = 0.65 + 0.35 * Math.cos(sectors * Math.atan2(y, x));
                    hue = starRadius * repetitions * 2 / star - phase;
                    break;
                case KALEIDOSCOPE_TRIANGLES:
                    double angle = Math.atan2(y, x) * sectors / (Math.PI * 2);
                    double folded = Math.abs(2 * (angle - Math.floor(angle)) - 1);
                    hue = Math.hypot(x, y) * repetitions * 2 + folded * Math.min(1, Math.hypot(x, y) * 5) - phase;
                    break;
                case KALEIDOSCOPE_FLOWER:
                    double flowerRadius = Math.hypot(x, y);
                    hue += flowerRadius * repetitions + 0.4 * Math.min(1, flowerRadius * 4)
                        * Math.cos(sectors * Math.atan2(y, x) + 2 * Math.PI * phase)
                        * Math.sin(flowerRadius * repetitions * Math.PI * 2);
                    break;
                case KALEIDOSCOPE_TUNNEL:
                    double tunnelRadius = Math.hypot(x, y);
                    hue = Math.log1p(tunnelRadius * 8) * repetitions - phase
                        + 0.25 * Math.min(1, tunnelRadius * 5) * Math.cos(sectors * Math.atan2(y, x) - phase * Math.PI * 2);
                    break;
                case RAINBOW_RINGS:
                    // Increasing radial hue moves each rainbow band outward over time.
                    hue = Math.hypot(x, y) * 3 - phase;
                    break;
                case PLASMA:
                    double time = phase * Math.PI * 2;
                    hue += 0.22 * (Math.sin(x * 9 + time) + Math.sin(y * 11 - time)
                        + Math.sin((x + y) * 7 + time) + Math.cos(Math.hypot(x, y) * 12 - time));
                    break;
                case AURORA:
                    double curtain = y * 3 + 0.35 * Math.sin(x * 8 + phase * Math.PI * 2)
                        + 0.15 * Math.sin(x * 17 - phase * Math.PI * 2);
                    // Green, cyan and violet ribbons at constant opacity.
                    hue = 0.5 + 0.22 * Math.sin(curtain * Math.PI * 2 + phase * Math.PI * 2);
                    break;
                default:
                    break;
            }
            rgb = palette.sample(hue);
        }
        return new Color(rgb.getRed(), rgb.getGreen(), rgb.getBlue(), (int) Math.round(255 * opacity));
    }

    private static int clamp(int value) { return Math.max(0, Math.min(100, value)); }
}

